from taf.fdsw.rc.interfaces.FDSW22A.fdsw import FDSW22A


class FDSW22B(FDSW22A):
    VERSION_NAME = 'FDSW22B'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW22B, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
